def solve(d):
    n=len(d)-1
    if n<2: return 0
    dp=[[0]*n for _ in range(n)]
    for size in range(2,n+1):
        for l in range(n-size+1):
            r=l+size-1
            dp[l][r]=min(dp[l][k]+dp[k+1][r]+d[l]*d[k+1]*d[r+1] for k in range(l,r))
    return dp[0][-1]
